import pytest
from isort.output import _with_from_imports

class MockConfig:
    no_inline_sort = False
    force_single_line = False
    only_sections = False
    combine_as_imports = True
    ignore_comments = False
    comment_prefix = '#'
    line_length = 80

@pytest.fixture
def mock_parsed():
    return {
        'imports': {
            'section': {
                'from': {
                    'module1': ['func1', 'func2'],
                }
            },
        },
        'categorized_comments': {
            'from': {},
            'above': {'from': {}},
            'nested': {},
            'straight': {}
        },
        'as_map': {
            'from': {
                'module1.func1': ['as_func1'],
                'module1.func2': ['as_func2']
            }
        }
    }

def test_with_valid_inputs(mock_parsed):
    config = MockConfig()  
    from_modules = ['module1']
    section = 'section'
    remove_imports = []
    import_type = 'import'

    result = _with_from_imports(mock_parsed, config, from_modules, section, remove_imports, import_type)
    assert isinstance(result, list)
    assert len(result) > 0

