class MockConfig:
    no_inline_sort = False
    force_single_line = False
    only_sections = False
    combine_as_imports = True
    ignore_comments = False
    comment_prefix = '#'
    line_length = 80

@pytest.fixture
def mock_parsed():
    return {
        'imports': {
            'section': {
                'from': {
                    'module1': ['func1', 'func2'],
                }
            },
        },
        'categorized_comments': {
            'from': {},
            'above': {'from': {}},
            'nested': {},
            'straight': {}
        },
        'as_map': {
            'from': {
                'module1.func1': ['as_func1'],
                'module1.func2': ['as_func2']
            }
        }
    }

def test_with_valid_inputs(mock_parsed):
    config = MockConfig()  
    from_modules = ['module1']
    section = 'section'
    remove_imports = []
    import_type = 'import'

    result = _with_from_imports(mock_parsed, config, from_modules, section, remove_imports, import_type)
    assert isinstance(result, list)
    assert len(result) > 0

def test_with_remove_imports(mock_parsed):
    config = MockConfig()
    from_modules = ['module1']
    section = 'section'
    remove_imports = ['module1.func1']
    import_type = 'import'

    result = _with_from_imports(mock_parsed, config, from_modules, section, remove_imports, import_type)
    assert 'module1.func1' not in result

def test_handle_star_imports(mock_parsed):
    config = MockConfig()
    from_modules = ['module1']
    section = 'section'
    remove_imports = []
    import_type = 'import'

    expected_star_imports = ['module1.func1', 'module1.func2']  # Define expected outputs based on behavior
    result = _with_from_imports(mock_parsed, config, from_modules, section, remove_imports, import_type)
    assert result == expected_star_imports
